module calendar(
    input CLK, input RST,
    output reg [5:0] Hours, Mins, Secs
);
    // TODO: Your code here. Remove the following lines once you add your implementation.
    initial begin
        Hours = 6'b0;
        Mins = 6'b0;
        Secs = 6'b0;
    end
    always @(posedge CLK or posedge RST) begin
        if(RST) begin
            Hours <= 6'b0;
            Mins <= 6'b0;
            Secs <= 6'b0;
        end
        else begin
            if(Secs == 6'd59) begin
                Secs <= 6'b0;
                if(Mins == 6'd59) begin
                    Mins <= 6'b0;
                    if(Hours == 6'd23) Hours <= 6'b0;
                    else Hours <= Hours + 1;
                end
                else Mins <= Mins + 1;
            end
            else Secs <= Secs + 1;
        end
    end
endmodule
